using Ginecologia.Modules.ConsultaMedica.Domain;
namespace Ginecologia.Modules.ConsultaMedica.Application;
public interface IConsultaRepository { Task<Consulta?> FindByIdAsync(Guid id, CancellationToken ct = default); Task<Consulta?> FindByAttachmentIdAsync(Guid attachmentId, CancellationToken ct = default); Task<PagedConsultaResult> ListAsync(Guid patientId, int page, int pageSize, CancellationToken ct = default); Task AddAsync(Consulta consulta, CancellationToken ct = default); Task SaveChangesAsync(CancellationToken ct = default); }
public sealed record PagedConsultaResult(IReadOnlyList<ConsultaDto> Items, int TotalCount, int Page, int PageSize);
public sealed record PrescriptionItemDto(Guid Id, int Orden, string Medicamento, string Dosis, string Via, string Frecuencia, string DuracionTexto) { public static PrescriptionItemDto From(PrescriptionItem x) => new(x.Id,x.Orden,x.Medicamento,x.Dosis,x.Via,x.Frecuencia,x.DuracionTexto); }
public sealed record ConsultaAttachmentDto(Guid Id, Guid ConsultaId, string NombreArchivo, string TipoContenido, int TamanoBytes, DateTime CreatedAtUtc) { public static ConsultaAttachmentDto From(ConsultaAttachment x) => new(x.Id,x.ConsultaId,x.NombreArchivo,x.TipoContenido,x.Contenido.Length,x.CreatedAtUtc); }
public sealed record ConsultaDto(Guid Id, Guid PatientId, DateOnly Fecha, ConsultaEstado Estado, Guid RegistradoPorId, DateTime CreatedAtUtc, DateTime UpdatedAtUtc, DateTime? FinalizadaAtUtc, int? PresionSistolica, int? PresionDiastolica, decimal? PesoKg, decimal? TallaCm, decimal? Imc, DateOnly? Fum, string MotivoConsulta, string? PadecimientoActual, string? HallazgosMamas, string? HallazgosCervixGenitales, string? HallazgosTactoBimanual, decimal? UltrasonidoEndometrioMm, string? UltrasonidoOvarioDerecho, string? UltrasonidoOvarioIzquierdo, string? UltrasonidoSacoGestacionalEmbrion, string? DiagnosticoCie, string? DiagnosticoDescripcion, string? EstudiosSolicitados, string? IndicacionesProximaCita, IReadOnlyList<PrescriptionItemDto> PrescriptionItems, IReadOnlyList<ConsultaAttachmentDto> Attachments)
{ public static ConsultaDto From(Consulta x) { decimal? imc = x.PesoKg is not null && x.TallaCm is not null ? Math.Round(x.PesoKg.Value / ((x.TallaCm.Value / 100m) * (x.TallaCm.Value / 100m)), 2) : null; return new(x.Id,x.PatientId,x.Fecha,x.Estado,x.RegistradoPorId,x.CreatedAtUtc,x.UpdatedAtUtc,x.FinalizadaAtUtc,x.PresionSistolica,x.PresionDiastolica,x.PesoKg,x.TallaCm,imc,x.Fum,x.MotivoConsulta,x.PadecimientoActual,x.HallazgosMamas,x.HallazgosCervixGenitales,x.HallazgosTactoBimanual,x.UltrasonidoEndometrioMm,x.UltrasonidoOvarioDerecho,x.UltrasonidoOvarioIzquierdo,x.UltrasonidoSacoGestacionalEmbrion,x.DiagnosticoCie,x.DiagnosticoDescripcion,x.EstudiosSolicitados,x.IndicacionesProximaCita,x.PrescriptionItems.OrderBy(i=>i.Orden).Select(PrescriptionItemDto.From).ToList(),x.Attachments.OrderByDescending(a=>a.CreatedAtUtc).Select(ConsultaAttachmentDto.From).ToList()); } }
public sealed record UpdateConsultaCommand(int? PresionSistolica, int? PresionDiastolica, decimal? PesoKg, decimal? TallaCm, DateOnly? Fum, string MotivoConsulta, string? PadecimientoActual, string? HallazgosMamas, string? HallazgosCervixGenitales, string? HallazgosTactoBimanual, decimal? UltrasonidoEndometrioMm, string? UltrasonidoOvarioDerecho, string? UltrasonidoOvarioIzquierdo, string? UltrasonidoSacoGestacionalEmbrion, string? DiagnosticoCie, string? DiagnosticoDescripcion, string? EstudiosSolicitados, string? IndicacionesProximaCita, IReadOnlyList<PrescriptionItemInput> PrescriptionItems);
public sealed class ConsultaNotFoundException(Guid id) : KeyNotFoundException($"No existe la consulta {id}.");
